#!/usr/bin/env python3
"""Finds tool attribution text ("generated by/with Claude Code", Co-Authored-By: Claude, session links) in commit
messages, pull request titles and bodies, and PR comments, and refuses or flags it.

The only place of the pattern list is PATTERNS below; the hook, the workflow and the tests use it through `find`.
Matching is case-insensitive. Normal prose about the product (Claude Code Cloud, CLAUDE.md, a rule that describes
the attribution) does not match: only the attribution forms listed in PATTERNS do.

Usage:
  python scripts/attribution_check.py commit-msg <message-file>   git commit-msg hook (hooks/commit-msg); exit 1 on a match
  python scripts/attribution_check.py text                        reads stdin; exit 1 on a match
  python scripts/attribution_check.py pr <number> [--repo <owner/name>] [--set-status]
      scans the commits, title, body, comments, reviews and review comments of a pull request through the GitHub API
      (token in GITHUB_TOKEN, repository in --repo or GITHUB_REPOSITORY); prints one line per finding (location only,
      never the text); --set-status writes the commit status `Attribution text check` on the PR head
      (red with findings, green without) and exits 0; without it the exit code is 1 on a match.
Standard library only.
"""
import argparse
import json
import os
import re
import sys
import urllib.error
import urllib.request

STATUS_CONTEXT = "Attribution text check"
FLAGS = re.IGNORECASE | re.MULTILINE

# name -> pattern. Keep one entry per attribution form; document a new one in README.md «Attribution text check» of TheBigNeo-AI/.github.
PATTERNS = {
    # Generated by Claude Code, Generated with [Claude Code](…), also created/made/written/authored; Markdown
    # decoration (* _ `) and hyphens around the words are allowed. Not «Created with Claude Code Cloud».
    "generated-by-or-with": r"\b(?:generated|created|made|written|authored|co-authored)[\s*_`-]+(?:by|with)[\s*_`\[-]+claude[\s*_`-]*code\b(?!\s+cloud)",
    # The literal form of the issue: "by claude code" (not «by Claude Code Cloud»).
    "by-claude-code": r"\bby[\s*_`\[-]+claude[\s*_`-]*code\b(?!\s+cloud)",
    # Co-Authored-By: Claude <model> <noreply@anthropic.com>, also after a quote or list marker (> - *).
    "co-authored-by": r"^[ \t]*(?:[>*-][ \t]*)*co-authored-by:[ \t]*claude\b",
    "anthropic-noreply": r"<noreply@anthropic\.com>",
    # Session links of cloud sessions and the trailer that carries them.
    "session-link": r"\bclaude\.ai/code/session_",
    "session-trailer": r"^[ \t]*(?:[>*-][ \t]*)*claude-session:",
}
COMPILED = {name: re.compile(pattern, FLAGS) for name, pattern in PATTERNS.items()}


def find(text):
    """Names of the patterns that match `text` (empty list: clean)."""
    return [name for name, regex in COMPILED.items() if regex.search(text or "")]


def strip_git_comments(message):
    """Drops the `#` lines git removes from a message (the template and the verbose diff are not part of it)."""
    return "\n".join(line for line in message.splitlines() if not line.startswith("#"))


# ---- GitHub ----

def github_request(method, path, body=None, token=None, base=None):
    """One API call; returns (parsed JSON, next page URL or None)."""
    base = base or os.environ.get("GITHUB_API_URL", "https://api.github.com")
    url = path if path.startswith("http") else base + path
    data = json.dumps(body).encode() if body is not None else None
    request = urllib.request.Request(url, data=data, method=method, headers={
        "Authorization": f"Bearer {token}", "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28", "User-Agent": "attribution-check"})
    with urllib.request.urlopen(request, timeout=30) as response:
        payload = response.read()
        link = response.headers.get("Link", "")
    match = re.search(r'<([^>]+)>;\s*rel="next"', link)
    return (json.loads(payload) if payload else None), (match.group(1) if match else None)


def paged(api, path):
    items, url = [], path + ("&" if "?" in path else "?") + "per_page=100"
    while url:
        page, url = api("GET", url)
        items.extend(page)
    return items


def scan_pull_request(api, repo, number):
    """Returns (head sha, findings); a finding is (location text, pattern names)."""
    pull, _ = api("GET", f"/repos/{repo}/pulls/{number}")
    findings = []

    def check(location, text):
        names = find(text)
        if names:
            findings.append((location, names))

    check("PR title", pull.get("title"))
    check("PR body", pull.get("body"))
    for commit in paged(api, f"/repos/{repo}/pulls/{number}/commits"):
        check(f"commit {commit['sha'][:7]}", commit["commit"]["message"])
    for comment in paged(api, f"/repos/{repo}/issues/{number}/comments"):
        check(f"comment {comment['id']}", comment.get("body"))
    for review in paged(api, f"/repos/{repo}/pulls/{number}/reviews"):
        check(f"review {review['id']}", review.get("body"))
    for comment in paged(api, f"/repos/{repo}/pulls/{number}/comments"):
        check(f"review comment {comment['id']}", comment.get("body"))
    return pull["head"]["sha"], findings


def status_payload(findings):
    if not findings:
        return {"state": "success", "context": STATUS_CONTEXT, "description": "No attribution text found."}
    where = ", ".join(location for location, _ in findings)
    description = f"Attribution text in: {where}"
    if len(description) > 140:
        description = description[:137] + "..."
    return {"state": "failure", "context": STATUS_CONTEXT, "description": description}


def run_pull_request(api, repo, number, set_status):
    sha, findings = scan_pull_request(api, repo, number)
    for location, names in findings:
        print(f"FOUND: {location} ({', '.join(names)})")
    if not findings:
        print("OK: no attribution text found")
    if set_status:
        api("POST", f"/repos/{repo}/statuses/{sha}", status_payload(findings))
        print(f"status {STATUS_CONTEXT} on {sha[:7]}: {'failure' if findings else 'success'}")
        return 0
    return 1 if findings else 0


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    sub = parser.add_subparsers(dest="mode", required=True)
    commit = sub.add_parser("commit-msg")
    commit.add_argument("file")
    sub.add_parser("text")
    pull = sub.add_parser("pr")
    pull.add_argument("number", type=int)
    pull.add_argument("--repo", default=os.environ.get("GITHUB_REPOSITORY"))
    pull.add_argument("--set-status", action="store_true")
    args = parser.parse_args(argv)

    if args.mode == "pr":
        if not args.repo:
            parser.error("--repo or GITHUB_REPOSITORY is required")
        token = os.environ.get("GITHUB_TOKEN")
        if not token:
            print("ERROR: GITHUB_TOKEN is not set", file=sys.stderr)
            return 2
        last = ["", ""]

        def api(method, path, body=None):
            last[:] = [method, path]
            return github_request(method, path, body, token)

        try:
            return run_pull_request(api, args.repo, args.number, args.set_status)
        except urllib.error.HTTPError as error:
            print(f"ERROR: GitHub API {error.code} {error.reason} for {last[0]} {last[1]}", file=sys.stderr)
            return 2
        except urllib.error.URLError as error:
            print(f"ERROR: GitHub API unreachable ({error.reason}) for {last[0]} {last[1]}", file=sys.stderr)
            return 2


    if args.mode == "commit-msg":
        with open(args.file, encoding="utf-8", errors="replace") as handle:
            text = strip_git_comments(handle.read())
    else:
        text = sys.stdin.read()
    names = find(text)
    if names:
        print("Commit refused: the message contains tool attribution text "
              f"({', '.join(names)}). Remove it and commit again (README.md «Attribution text check» of TheBigNeo-AI/.github).",
              file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
